META = dict(nama="Forestry", jp="林業", emoji="🌲", co="林業会社・森林組合")
SPEC = dict(kerja="山の仕事の安全をとても大切にしている", kerja_id="sangat mengutamakan keselamatan kerja di hutan", soal={
 "shibou-01": ("なぜ林業の仕事を選びましたか。", "Mengapa Anda memilih pekerjaan kehutanan?", "自然の中で、体を動かして働くのが好きです。森を守りながら、木を育てる仕事に興味があります。", "Saya suka bekerja bergerak di alam. Saya tertarik pada pekerjaan merawat pohon sambil menjaga hutan.", [("林業", "kehutanan"), ("森", "hutan"), ("育てる", "menumbuhkan"), ("守る", "menjaga")]),
 "shibou-02": ("なぜ日本で林業を学びたいですか。", "Mengapa Anda ingin belajar kehutanan di Jepang?", "日本は国の多くが森で、木を植えて育てる技術が進んでいると聞きました。その方法を学びたいです。", "Saya dengar sebagian besar wilayah Jepang adalah hutan dan teknik menanam serta merawat pohonnya maju. Saya ingin mempelajarinya.", [("技術", "teknik"), ("植える", "menanam"), ("学ぶ", "belajar")]),
 "shibou-04": ("この仕事に興味を持った理由は何ですか。", "Apa alasan Anda tertarik pada pekerjaan ini?", "木が少しずつ大きくなるのを見るのが好きです。森を次の世代に残す仕事に、やりがいを感じます。", "Saya suka melihat pohon tumbuh sedikit demi sedikit. Saya merasa pekerjaan mewariskan hutan kepada generasi berikutnya itu bermakna.", [("世代", "generasi"), ("残す", "mewariskan"), ("やりがい", "rasa bermakna")]),
 "shibou-05": ("林業の仕事で、一番楽しみなことは何ですか。", "Apa yang paling Anda nantikan dari pekerjaan kehutanan?", "木を植えて、大きく育つのを見ることです。日本の山の仕事の方法も学びたいです。", "Menanam pohon dan melihatnya tumbuh besar. Saya juga ingin belajar cara kerja di hutan Jepang.", [("植林", "penanaman pohon"), ("育つ", "tumbuh"), ("楽しみ", "dinantikan")]),
 "shigoto-01": ("林業の主な仕事は何だと思いますか。", "Menurut Anda, apa pekerjaan utama kehutanan?", "木を植えたり、草を刈ったり、木を切って運んだりする仕事だと思います。", "Saya kira pekerjaannya menanam pohon, memotong rumput, serta menebang dan mengangkut kayu.", [("植林", "penanaman pohon"), ("伐採", "penebangan"), ("下刈り", "pembabatan rumput")]),
 "shigoto-02": ("朝早くから働くことはできますか。", "Apakah Anda bisa bekerja dari pagi buta?", "はい、できます。山の仕事は朝が早いと聞いています。早く寝て、準備をします。", "Ya, bisa. Saya dengar kerja di hutan dimulai pagi sekali. Saya tidur lebih awal dan bersiap.", [("早朝", "pagi buta"), ("準備", "persiapan"), ("山", "gunung/hutan")]),
 "shigoto-03": ("暑い日や寒い日でも、山で働けますか。", "Bisakah Anda bekerja di hutan walau cuaca panas atau dingin?", "はい、大丈夫です。暑い日はこまめに水を飲んで、寒い日は服をたくさん着ます。", "Ya, tidak masalah. Saat panas saya sering minum air dan saat dingin memakai banyak lapis pakaian.", [("暑い", "panas"), ("寒い", "dingin"), ("こまめに", "sering/rutin")]),
 "shigoto-04": ("雨や雪の日は、どう思いますか。", "Bagaimana pendapat Anda tentang hari hujan atau salju?", "山の道は、すべりやすくて危ないです。天気が悪い日は、責任者の判断に従って、無理をしません。", "Jalan di hutan licin dan berbahaya. Saat cuaca buruk, saya mengikuti keputusan penanggung jawab dan tidak memaksakan diri.", [("すべる", "licin"), ("判断", "keputusan"), ("危ない", "berbahaya")]),
 "shigoto-05": ("山を歩いたり、重い道具を持ったりする体力はありますか。", "Apakah Anda punya stamina untuk berjalan di gunung dan membawa alat berat?", "はい、あります。毎日運動をして、体力をつけています。山を歩くのも、少しずつ慣れたいです。", "Ya, ada. Saya berolahraga setiap hari. Saya juga ingin terbiasa berjalan di gunung sedikit demi sedikit.", [("体力", "stamina"), ("山道", "jalan gunung"), ("慣れる", "terbiasa")]),
 "shigoto-06": ("山の近くで、家に帰れない日や、寮で生活する期間があっても大丈夫ですか。", "Apakah Anda baik-baik saja bila tidak bisa pulang beberapa hari atau tinggal di asrama dekat hutan?", "はい、大丈夫です。家族とは、連絡をとります。みんなで協力して、がんばります。", "Ya, tidak masalah. Saya akan menghubungi keluarga. Kami akan bekerja sama dan berusaha.", [("寮", "asrama"), ("連絡", "menghubungi"), ("協力", "kerja sama")]),
 "shigoto-07": ("チェーンソーや道具を使うとき、何に気をつけますか。", "Apa yang Anda perhatikan saat memakai gergaji mesin dan alat?", "必ず使い方を教えてもらってから使います。使う前に、道具の状態を確認します。まわりに人がいないか、見ます。", "Saya memakainya hanya setelah diajari cara pakainya. Sebelum dipakai saya memeriksa kondisi alat. Saya melihat apakah ada orang di sekitar.", [("チェーンソー", "gergaji mesin"), ("確認", "memastikan"), ("まわり", "sekitar")]),
 "shigoto-08": ("虫や動物が近くにいる環境でも大丈夫ですか。", "Apakah Anda baik-baik saja di lingkungan yang dekat serangga dan hewan liar?", "はい、大丈夫です。長そでの服を着て、虫よけを使います。動物を見たら、近づかないで先輩に知らせます。", "Ya, tidak masalah. Saya memakai baju lengan panjang dan obat anti-serangga. Kalau melihat hewan, saya tidak mendekat dan memberi tahu senior.", [("虫よけ", "anti-serangga"), ("動物", "hewan"), ("近づく", "mendekat")]),
 "shigoto-09": ("森の仕事で、大切なことは何だと思いますか。", "Menurut Anda, apa yang penting dalam pekerjaan hutan?", "安全に作業することだと思います。木は、育つのに長い時間がかかるので、ていねいに仕事をすることも大切です。", "Menurut saya, bekerja dengan aman. Karena pohon butuh waktu lama untuk tumbuh, bekerja dengan teliti juga penting.", [("安全", "keselamatan"), ("ていねい", "teliti"), ("長い時間", "waktu lama")]),
 "shigoto-10": ("木を植えてから、切るまで、どんな作業がありますか。", "Pekerjaan apa saja sejak menanam sampai menebang pohon?", "木を植えて、草を刈って、枝を切ります。大きくなったら、切って運びます。何十年もかかります。", "Menanam pohon, memotong rumput, dan memangkas cabang. Setelah besar, pohon ditebang dan diangkut. Butuh puluhan tahun.", [("枝打ち", "pemangkasan cabang"), ("間伐", "penjarangan"), ("何十年", "puluhan tahun")]),
 "shigoto-11": ("木を切るとき、まわりの人と、どのように安全を守りますか。", "Bagaimana Anda menjaga keselamatan dengan orang sekitar saat menebang pohon?", "木を切る前に、大きい声で知らせます。倒れる方向に、人がいないか確認します。", "Sebelum menebang, saya memberi tahu dengan suara keras. Saya memastikan tidak ada orang di arah pohon akan tumbang.", [("倒れる", "tumbang"), ("方向", "arah"), ("合図", "aba-aba")]),
 "shigoto-12": ("山で、道に迷ったら、どうしますか。", "Apa yang Anda lakukan kalau tersesat di gunung?", "あわてないで、その場に止まります。すぐに責任者に連絡して、場所を伝えます。", "Saya tidak panik dan berhenti di tempat. Saya segera menghubungi penanggung jawab dan menyampaikan lokasi.", [("迷う", "tersesat"), ("あわてる", "panik"), ("場所", "lokasi")]),
 "shigoto-13": ("日本の森や、木の仕事について、知っていることはありますか。", "Apa yang Anda ketahui tentang hutan dan pekerjaan kayu di Jepang?", "日本には、スギやヒノキの森が多いと聞きました。木を切るだけでなく、植えて育てることも大切だと思います。", "Saya dengar di Jepang banyak hutan sugi dan hinoki. Menurut saya bukan hanya menebang, menanam dan merawat juga penting.", [("スギ", "sugi"), ("ヒノキ", "hinoki"), ("森林", "hutan")]),
 "taiou-02": ("木や道具を、だめにしてしまったら、どうしますか。", "Apa yang Anda lakukan kalau merusak pohon atau alat?", "すぐに正直に報告します。どうしてそうなったか考えて、次は同じことをしないようにします。", "Saya segera melapor jujur. Saya memikirkan penyebabnya dan berusaha tidak mengulangi.", [("だめにする", "merusak"), ("報告", "melapor"), ("原因", "penyebab")]),
 "taiou-06": ("天気が急に悪くなって、予定が変わったら、どうしますか。", "Apa yang Anda lakukan kalau cuaca mendadak memburuk dan rencana berubah?", "責任者の指示をよく聞いて、安全を第一に動きます。すぐに山から下りるときもあります。", "Saya mendengarkan instruksi penanggung jawab dan bergerak dengan mengutamakan keselamatan. Kadang harus segera turun gunung.", [("急に", "mendadak"), ("指示", "instruksi"), ("山を下りる", "turun gunung")]),
 "taiou-08": ("山の作業が、急に早く終わったり、遅くなったりしたら、どうしますか。", "Apa yang Anda lakukan kalau pekerjaan di hutan mendadak selesai lebih awal atau lebih lambat?", "連絡をよく聞いて、すぐに準備します。道具の片づけも、きちんとします。", "Saya mendengar pemberitahuan dan segera bersiap. Saya juga membereskan alat dengan benar.", [("片づける", "membereskan"), ("準備", "persiapan"), ("連絡", "pemberitahuan")]),
 "taiou-11": ("山の仕事で疲れているとき、どう気持ちを保ちますか。", "Bagaimana Anda menjaga semangat saat lelah bekerja di hutan?", "疲れたときは、無理をしないで、休みます。しっかり寝て、食事をとって、体調を保ちます。", "Saat lelah, saya tidak memaksakan diri dan beristirahat. Saya tidur cukup, makan baik, dan menjaga kondisi badan.", [("疲れる", "lelah"), ("体調", "kondisi badan"), ("休む", "istirahat")]),
 "taiou-12": ("山の人に、方言で話されて分からないとき、どうしますか。", "Apa yang Anda lakukan kalau orang di desa gunung berbicara dialek dan Anda tidak paham?", "「すみません、ゆっくりお願いします」と言います。分からない言葉は、メモして、あとで聞きます。", "Saya bilang \"Maaf, tolong lebih pelan\". Kata yang tidak paham saya catat dan tanyakan nanti.", [("方言", "dialek"), ("ゆっくり", "pelan"), ("メモ", "catatan")]),
 "tim-01": ("山の作業で、チームの人と、どのように作業を分けますか。", "Dalam pekerjaan hutan, bagaimana Anda membagi tugas dengan tim?", "責任者の指示で、木を切る人、運ぶ人などに分かれます。声をかけ合って、安全に作業します。", "Sesuai instruksi penanggung jawab, ada yang menebang dan ada yang mengangkut. Kami saling memberi aba-aba agar aman.", [("分担", "pembagian tugas"), ("声をかけ合う", "saling memberi aba-aba"), ("責任者", "penanggung jawab")]),
 "tim-02": ("先輩の指示が分からなかったとき、どうしますか。", "Apa yang Anda lakukan kalau tidak paham instruksi senior?", "すぐに「もう一度お願いします」と聞きます。山では、分からないまま動くと、とても危ないからです。", "Saya segera meminta \"Tolong ulangi\". Di hutan, bergerak tanpa paham sangat berbahaya.", [("指示", "instruksi"), ("危ない", "berbahaya"), ("確認", "memastikan")]),
 "tim-03": ("山の中で、離れた場所にいる仲間と、どのように連絡しますか。", "Bagaimana Anda berkomunikasi dengan rekan yang berjauhan di hutan?", "決められた合図や、無線を使います。大きい声ではっきり伝えます。", "Saya memakai isyarat yang ditentukan atau radio. Saya menyampaikan dengan jelas dan suara keras.", [("無線", "radio komunikasi"), ("合図", "isyarat"), ("伝える", "menyampaikan")]),
 "tim-04": ("山の仲間と、どのように仲良くなりたいですか。", "Bagaimana Anda ingin akrab dengan rekan di hutan?", "毎日、元気にあいさつをします。仕事のやり方を教えてもらったときは、「ありがとうございます」と言います。", "Setiap hari saya menyapa dengan semangat. Saat diajari cara kerja, saya mengatakan \"Terima kasih\".", [("あいさつ", "salam"), ("仲間", "rekan"), ("感謝", "rasa terima kasih")]),
 "anzen-01": ("山で作業するとき、必ず身につけるものは何ですか。", "Apa yang wajib dikenakan saat bekerja di hutan?", "ヘルメット、安全靴、手袋を必ず着けます。チェーンソーを使うときは、保護ズボンも着けます。", "Saya wajib memakai helm, sepatu keselamatan, dan sarung tangan. Saat memakai gergaji mesin saya juga memakai celana pelindung.", [("ヘルメット", "helm"), ("保護ズボン", "celana pelindung"), ("安全靴", "sepatu keselamatan")]),
 "anzen-02": ("チェーンソーを使うとき、事故を防ぐために何をしますか。", "Apa yang Anda lakukan untuk mencegah kecelakaan saat memakai gergaji mesin?", "必ず両手で持ちます。動いているときは、まわりに人を近づけません。置くときは、エンジンを止めます。", "Saya selalu memegang dengan dua tangan. Saat menyala, saya tidak membiarkan orang mendekat. Saat meletakkannya, saya mematikan mesin.", [("エンジンを止める", "mematikan mesin"), ("両手", "dua tangan"), ("事故", "kecelakaan")]),
 "anzen-03": ("木が倒れるとき、どうやって安全を守りますか。", "Bagaimana Anda menjaga keselamatan saat pohon tumbang?", "木が倒れる方向を、よく確認します。倒れ始めたら、決められた逃げる道に、すぐ避難します。", "Saya memastikan arah tumbang dengan baik. Begitu mulai tumbang, saya segera menyelamatkan diri lewat jalur yang ditentukan.", [("倒れる", "tumbang"), ("避難", "menyelamatkan diri"), ("方向", "arah")]),
 "anzen-04": ("ハチやヘビ、クマを見つけたら、どうしますか。", "Apa yang Anda lakukan kalau menemukan tawon, ular, atau beruang?", "近づかないで、ゆっくり離れます。大きい声は出さないで、すぐに責任者に知らせます。", "Saya tidak mendekat dan menjauh pelan-pelan. Saya tidak berteriak dan segera memberi tahu penanggung jawab.", [("ハチ", "tawon"), ("ヘビ", "ular"), ("クマ", "beruang")]),
 "seikatsu-07": ("山の近くの町での生活に、不便なことがあっても大丈夫ですか。", "Apakah Anda baik-baik saja dengan ketidaknyamanan hidup di kota dekat pegunungan?", "大丈夫です。お店が遠いときは、まとめて買い物をします。バスの時間も調べます。", "Tidak masalah. Kalau toko jauh, saya belanja sekaligus. Saya juga mengecek jadwal bus.", [("不便", "tidak nyaman"), ("まとめて", "sekaligus"), ("調べる", "mengecek")]),
 "seikatsu-08": ("日本の山や、季節について、知っていることはありますか。", "Apa yang Anda ketahui tentang gunung dan musim di Jepang?", "日本には、春夏秋冬があって、山の様子が変わると聞きました。冬は雪が多い所もあると知っています。", "Saya dengar Jepang punya empat musim dan pemandangan gunung berubah. Saya tahu ada daerah yang bersalju lebat di musim dingin.", [("四季", "empat musim"), ("雪", "salju"), ("様子", "keadaan")]),
 "mokuhyou-05": ("日本で林業を学んだあと、自分の国でどんなことをしたいですか。", "Setelah belajar kehutanan di Jepang, apa yang ingin Anda lakukan di negara sendiri?", "日本で学んだ木の育て方や、山での安全の方法を使って、自分の国の森も守りたいです。", "Saya ingin menjaga hutan di negara saya dengan memakai cara menumbuhkan pohon dan cara keselamatan di hutan yang saya pelajari di Jepang.", [("森", "hutan"), ("守る", "menjaga"), ("安全", "keselamatan")]),
})
